CREATE OR REPLACE FUNCTION ECAMS.VERSION_SEL(ITEMID IN VARCHAR2)
RETURN INTEGER
IS
  VCNT INT := 0;

--최종신청기록이 버전별가져오기 여부체크 및 버전별 가져오기인 경우 버전추출

CURSOR REQ_CUR IS
SELECT A.CR_QRYCD,B.CR_VERSION
  FROM CMR1000 A, CMR1010 B
 WHERE B.CR_ITEMID=ITEMID
   AND B.CR_STATUS<>'3'
   AND A.CR_ACPTNO=B.CR_ACPTNO
   AND A.CR_STATUS<>'3'
 ORDER BY A.CR_ACPTDATE DESC;

BEGIN
    FOR REQ_FET IN REQ_CUR LOOP
        --IF REQ_FET.CR_QRYCD = '02' THEN
        --    VCNT := REQ_FET.CR_VERSION;
        --ELSE
        --    VCNT := 0;
        --END IF;
        VCNT := REQ_FET.CR_VERSION;
        EXIT;
    END LOOP;
RETURN VCNT;
END;